commands.command:
/bin/zsh -lc "node --input-type=module - <<'ASSESSMENT_JS'
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import assert from 'node:assert/strict';
const assessment = {
  \"stage\": \"stage.plan\",
  \"known_blockers\": [],
  \"verification_scope\": {
    \"checked\": [
      {
        \"command\": \"node scripts/lifecycle-status --checkpoint checkpoint.json\",
        \"exit_code\": 0
      },
      {
        \"command\": \"node scripts/query-lifecycle-context --mode route --stage stage.plan --work-unit work-unit.plan-requirements --include modes\",
        \"exit_code\": 0
      }
    ],
    \"checkpoint_observations\": {
      \"repository_mode\": \"project-instance\",
      \"mode\": \"route\",
      \"status\": \"routing\",
      \"next_work_unit\": \"work-unit.plan-requirements\",
      \"owner\": \"未登记\",
      \"context_reconciliation\": \"pending；ref 为 null，evidence_refs 为空，尚未核验对账内容和摘要。\",
      \"artifacts_and_gates\": \"均为空；没有已登记的产物或门禁结论，不能据此认定阶段完成或门禁通过。\"
    },
    \"status_checks\": [
      {
        \"id\": \"registered-blockers\",
        \"status\": \"passed\",
        \"refs\": [
          \"checkpoint.json\"
        ],
        \"reason\": \"仅读取已登记阻塞，不代表完整就绪\"
      },
      {
        \"id\": \"stage-and-route\",
        \"status\": \"passed\",
        \"refs\": [
          \".template-spec/process/lifecycle-registry.yaml\",
          \".agents/skills/yss-product-lifecycle/references/orchestration-contract.yaml\"
        ],
        \"reason\": \"仅检查身份与路由存在，不计算完整 frontier\"
      },
      {
        \"id\": \"context-reconciliation\",
        \"status\": \"not-checked\",
        \"refs\": [],
        \"reason\": \"读取登记状态；当前对账内容和摘要仍须由原验证器核验\"
      },
      {
        \"id\": \"registered-gates\",
        \"status\": \"passed\",
        \"refs\": [
          \"checkpoint.json\"
        ],
        \"reason\": \"仅检查登记的 blocked/stale 标志\"
      },
      {
        \"id\": \"evidence-readable\",
        \"status\": \"passed\",
        \"refs\": [],
        \"reason\": \"仅检查已引用证据可读，不证明证据完整或当前有效\"
      },
      {
        \"id\": \"artifact-digests\",
        \"status\": \"not-checked\",
        \"refs\": [],
        \"reason\": \"未核验批准资产原字节摘要；恢复时运行资产所有者的适用预检\"
      },
      {
        \"id\": \"approval-validity\",
        \"status\": \"not-checked\",
        \"refs\": [
          \"checkpoint.json\"
        ],
        \"reason\": \"未核验真实决定、延续、外部审批及完整执行授权\"
      },
      {
        \"id\": \"stage-tracking\",
        \"status\": \"not-checked\",
        \"refs\": [
          \"checkpoint.json\"
        ],
        \"reason\": \"未登记追踪；按实例既有兼容或显式迁移入口处理，不自动补建\"
      }
    ],
    \"not_checked\": [
      \"未运行 scripts/verify-lifecycle-checkpoint、阶段流转预检或完整 ready-for-agent 计算；未重建完整待办和依赖。\",
      \"未核验实际影响面、Plan 内容及退出条件、批准有效性、实施合同与实施授权；未登记的信息不能推断为通过。\",
      \"未检查外部实现仓库、真实 tracker、构建、测试、CI 或发布状态；未访问网络或执行 Git、包管理器命令。\"
    ],
    \"interpretation\": \"known_blockers 为空仅表示只读入口未发现已登记阻塞。Context 对账仍 pending，阶段追踪未登记；本次未确认可以实施。\",
    \"execution_authorization\": \"not-evaluated\",
    \"boundary\": \"仅在隔离 fixture 内进行 test-data-only 状态检查；结果不构成真实批准或真实构建、交付验证。\",
    \"source_digests\": {
      \"checkpoint\": {
        \"ref\": \"checkpoint.json\",
        \"digest\": \"sha256:c07bae643950ab30962c2967872122fc9f13abc28a5f24f6ab5a8db6ca73cc90\"
      },
      \"registry\": {
        \"ref\": \".template-spec/process/lifecycle-registry.yaml\",
        \"digest\": \"sha256:e9fbae32a659edff9444301ada1c1fdfc36ae0e8c45c8148e143aa04d761f83e\"
      },
      \"orchestration\": {
        \"ref\": \".agents/skills/yss-product-lifecycle/references/orchestration-contract.yaml\",
        \"digest\": \"sha256:9d3ff488dc7778bdd12e210928891871e27cd434bc9c6442b03a22bd105b0926\"
      }
    }
  },
  \"execution_authorized\": false,
  \"next_action\": \"本次保存结论后停止，保持 checkpoint 和流程状态不变。后续若获准恢复，先运行 node scripts/verify-lifecycle-checkpoint checkpoint.json，并核验当前来源、Context 对账、适用门禁、决定或授权延续及允许写范围，再由主控判断是否恢复 work-unit.plan-requirements；该建议不授予实施权限。\"
};
const digest = bytes => 'sha256:' + createHash('sha256').update(bytes).digest('hex');
const refs = [...new Set([
  ...Object.values(assessment.verification_scope.source_digests).map(item => item.ref),
  'checkpoint.json', 'yss-project.yaml', 'CONTEXT.md', 'AGENTS.md',
  '.agents/skills/yss-product-lifecycle/SKILL.md',
  '.template-spec/agents/yss-skill-registry.yaml'
])];
assert.equal(existsSync('assessment.json'), false, 'assessment.json 已存在，禁止覆盖');
const originals = new Map(refs.map(ref => [ref, readFileSync(ref)]));
for (const source of Object.values(assessment.verification_scope.source_digests)) {
  assert.equal(digest(originals.get(source.ref)), source.digest, '状态来源已变化：' + source.ref);
}
writeFileSync('assessment.json', JSON.stringify(assessment, null, 2) + '\\n', {flag: 'wx'});
const saved = JSON.parse(readFileSync('assessment.json', 'utf8'));
assert.deepEqual(Object.keys(saved), ['stage', 'known_blockers', 'verification_scope', 'execution_authorized', 'next_action']);
assert.deepEqual(saved, assessment);
for (const [ref, bytes] of originals) assert.ok(bytes.equals(readFileSync(ref)), '原输入发生变化：' + ref);
console.log(JSON.stringify({created: 'assessment.json', assessment_json_valid: true, original_inputs_unchanged: refs, execution_authorized: saved.execution_authorized}, null, 2));

ASSESSMENT_JS"

